DROP TABLE IF EXISTS reagents_dedup;
CREATE TABLE reagents_dedup (
    row_id INTEGER PRIMARY KEY,
    cas_number INTEGER,
    name TEXT,
    total_quantity INTEGER,
    location TEXT,
    notes TEXT,
    primary_lot_id TEXT
);

CREATE TEMP TABLE reagent_groups (cas_number INTEGER, name TEXT, total_quantity INTEGER, notes TEXT, primary_lot_id TEXT);
INSERT INTO reagent_groups SELECT cas_number, name, SUM(quantity) as total_quantity, notes, MIN(lot_id) as primary_lot_id FROM reagents GROUP BY cas_number;
CREATE TEMP TABLE location_groups (cas_number INTEGER, location_list TEXT);
INSERT INTO location_groups SELECT cas_number, GROUP_CONCAT(location, ', ') as location_list FROM reagents GROUP BY cas_number;
INSERT INTO reagents_dedup (row_id, cas_number, name, total_quantity, location, notes, primary_lot_id) SELECT rowid, rg.cas_number, rg.name, rg.total_quantity, lg.location_list, rg.notes, rg.primary_lot_id FROM reagent_groups rg JOIN location_groups lg ON rg.cas_number = lg.cas_number;
